import{_ as o,o as t,c as d,a2 as r}from"./chunks/framework.CuUVYbLV.js";const u=JSON.parse('{"title":"示例目录","description":"rolebox 仓库 examples/ 的 7 个示例 — 名称、教什么、对应教程章节与仓库路径","frontmatter":{"title":"示例目录","description":"rolebox 仓库 examples/ 的 7 个示例 — 名称、教什么、对应教程章节与仓库路径"},"headers":[],"relativePath":"02-Guide/examples.md","filePath":"02-Guide/examples.md"}'),a={name:"02-Guide/examples.md"};function l(c,e,s,i,h,m){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="示例目录-examples" tabindex="-1">示例目录（Examples） <a class="header-anchor" href="#示例目录-examples" aria-label="Permalink to &quot;示例目录（Examples）&quot;">​</a></h1><p>rolebox 仓库的 <code>examples/</code> 下有 7 个示例：5 个角色目录与 2 个支撑示例（自定义 Hook 模块、dsh 平台补丁）。本页是它们的索引，逐步走查见对应的教程章节与指南页。早期版本里的四个协作示例角色已随声明式多代理子系统一起移除，示例总数因此为 7；移除范围见<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>。</p><blockquote><p>相关：<a href="/rolebox-docs/02-Guide/getting-started.html">教程总览与学习路径</a> — 七章教程的入口｜<a href="/rolebox-docs/02-Guide/create-a-role.html">创建角色</a> — 自己写一个角色目录｜<a href="/rolebox-docs/02-Guide/custom-hooks.html">自定义 Hook</a> — Hook 模块的完整 API</p></blockquote><h2 id="示例一览" tabindex="-1">示例一览 <a class="header-anchor" href="#示例一览" aria-label="Permalink to &quot;示例一览&quot;">​</a></h2><p>所有示例位于 <a href="https://github.com/EricMoin/rolebox/tree/main/examples" target="_blank" rel="noreferrer">rolebox/examples</a>。</p><table tabindex="0"><thead><tr><th>示例</th><th>教什么</th><th>对应教程章节</th><th>仓库路径</th></tr></thead><tbody><tr><td>code-reviewer</td><td>完整角色目录：<code>role.yaml</code> + 角色级技能 + 自定义函数 + 权限白名单</td><td><a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">教程 02</a>、<a href="/rolebox-docs/02-Guide/tutorial/03-functions.html">教程 03</a></td><td><code>examples/code-reviewer/</code></td></tr><tr><td>tech-writer</td><td>最小可用角色：7 行 <code>role.yaml</code>，只有 name / description / prompt 加一个全局技能</td><td><a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">教程 02</a></td><td><code>examples/tech-writer/</code></td></tr><tr><td>team-lead</td><td>两种子代理声明：内联 <code>subagents:</code> 与文件式 <code>subagents/{name}/role.yaml</code>，以及字段继承</td><td><a href="/rolebox-docs/02-Guide/tutorial/04-team.html">教程 04</a></td><td><code>examples/team-lead/</code></td></tr><tr><td>hooks</td><td>自定义 Hook：<code>onToolAfter</code> 拦截工具调用后用 <code>ctx.inject()</code> 注入提示</td><td>—（见<a href="/rolebox-docs/02-Guide/custom-hooks.html">自定义 Hook</a>）</td><td><code>examples/hooks/</code></td></tr><tr><td>review-team</td><td>评审回环的两名参与者（Coder / Reviewer），流程由 <code>graph_*</code> 工具在运行时表达</td><td><a href="/rolebox-docs/02-Guide/tutorial/04-team.html">教程 04</a>、<a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05</a></td><td><code>examples/review-team/</code></td></tr><tr><td>review-team-custom</td><td>三人线性流水线（Researcher → Writer → Editor）的参与者声明</td><td><a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05</a></td><td><code>examples/review-team-custom/</code></td></tr><tr><td>dsh</td><td>dsh 平台集成：向 profile 的 <code>cordis.patch.yml</code> 插入一行 rolebox 插件</td><td>—（见<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>）</td><td><code>examples/dsh/</code></td></tr></tbody></table><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><ul><li><strong>角色示例可整目录复制</strong>：表中前三个与两个 review-team 示例都含 <code>role.yaml</code>，拷进你的角色目录再按需改写即可。</li><li><strong><code>code-reviewer/</code> 是文件布局的样板</strong>：<code>skills/review-checklist/SKILL.md</code> 演示角色级技能，<code>functions/plan.md</code> 演示自定义函数。</li><li><strong><code>team-lead/</code> 同时演示两种子代理写法</strong>：<code>role.yaml</code> 里的内联 Implementer，以及 <code>subagents/researcher/</code> 下自带技能的文件式子代理。</li><li><strong>两个支撑示例不是角色目录</strong>：<code>hooks/no-console-log.js</code> 要在 <code>role.yaml</code> 的 <code>hooks.custom</code> 中注册；<code>dsh/cordis.patch.yml</code> 要复制进 dsh profile。</li><li><strong>参与者不等于流程</strong>：两个 review-team 示例只声明有哪些子代理，评审回环或线性流水线由运行时建图表达。</li></ul><h2 id="与教程的分工" tabindex="-1">与教程的分工 <a class="header-anchor" href="#与教程的分工" aria-label="Permalink to &quot;与教程的分工&quot;">​</a></h2><p>逐示例的代码走查不在本页重复：<code>code-reviewer</code> 的完整构建是<a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">教程 02</a>与<a href="/rolebox-docs/02-Guide/tutorial/03-functions.html">教程 03</a>的主线，<code>review-team</code> 的团队与图编排是<a href="/rolebox-docs/02-Guide/tutorial/04-team.html">教程 04</a>与<a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05</a>的主线；其余示例按上表的链接跳转。</p>',10)])])}const p=o(a,[["render",l]]);export{u as __pageData,p as default};
